// World map data: regions, sub-areas, enemy themes and the monster spots of every sub-area.
// WP20: everything comes from window.WorldGen (js/world-gen.js, generated by tools/build-world.mjs from data/regions/*.json), so a new
// region is a JSON file and no code edit. Node positions are fixed by the generator (the map is the same on every run); only the
// enemies inside each battle change between runs. World units: 1 tile = 64 units, y is negative north of the Camp.
(function (root) {
  'use strict';
  const Engine = root.Engine;
  const WG = root.WorldGen || (typeof require !== 'undefined' ? require('./world-gen.js') : null);
  if (!WG) throw new Error('world-data.js needs window.WorldGen (js/world-gen.js)');

  // Free exploration: every monster spot of an unlocked sub-area is open.
  //   lm       = landmark kind (+ lmLabel)    lv / bossLv = level range of ordinary spots / of the boss
  //   unlocks  = sub-areas revealed by this sub-area's boss; from = the sub-area (or 'camp') that leads here
  //   poi      = kind of the optional non-battle spot: 'shrine' (spring: heal OR upgrade) or 'treasure' (supply cache, sometimes guarded); free of Rations.
  //   WP13 also adds a 'shop' (gold) and an 'event' (text vignette) node per sub-area (generator: subareas[id].shop / .event)
  // ---------- Deterministic helpers ----------
  function hash(s) { let h = 2166136261; for (const ch of String(s)) { h ^= ch.charCodeAt(0); h = Math.imul(h, 16777619); } return (h >>> 0) % 2147483646 + 1; }
  function rng(seed) { let s = typeof seed === 'number' ? seed : hash(seed); return () => { s = (s * 16807) % 2147483647; return (s - 1) / 2147483646; }; }

  // ---------- Regions and sub-areas (from the generator) ----------
  const T = WG.tile || 64;
  const CAMP_REGION = WG.regions.find((r) => r.kind === 'camp');
  const CHAIN = WG.regions.filter((r) => r.kind !== 'camp').sort((a, b) => a.ring - b.ring);
  const REGIONS = CHAIN.map((r) => r.name);
  // World box (tiles -> units): the union of every region box.
  const box = WG.regions.reduce((b, r) => [Math.min(b[0], r.origin[0]), Math.min(b[1], r.origin[1]), Math.max(b[2], r.origin[0] + r.size), Math.max(b[3], r.origin[1] + r.size)], [1e9, 1e9, -1e9, -1e9]).map((v) => v * T);
  const MAP_BOX = box, MAP_W = box[2] - box[0], MAP_H = box[3] - box[1];

  const SUBAREAS = [], GUARDED = [], SHOPS = [], THEMES = {}, FINAL_SUBS = [];
  for (const r of CHAIN) {
    for (const id of r.subIds) {
      const L = r.subareas[id];
      if (L.guarded) GUARDED.push(id);
      if (L.shopFlag && L.shop) SHOPS.push(id);
      if (L.final && !(r.exit && r.exit.to)) FINAL_SUBS.push(id);
      THEMES[id] = L.theme;
      SUBAREAS.push({
        id, region: r.name, regionId: r.id, name: L.name, biome: L.biome, lv: L.lv, bossLv: L.bossLv, unlocks: L.unlocks || [], from: L.from || 'camp', poi: L.poiKind || null,
        bounds: L.bounds, shape: null, entry: L.entry, boss: L.boss, elites: L.elites || [], spots: L.spots || [], poiPos: L.poi || null, shopPos: L.shop || null, eventPos: L.event || null, wpPos: L.wp || null, secretPos: L.secret || null,
        landmark: Object.assign({}, L.landmark, { kind: L.lm, label: L.lmLabel || L.name }),
        regionIndex: Math.max(0, r.ring - 1), bossDef: L.bossDef || id, final: !!L.final,
      });
    }
  }
  const SUB_BY = Object.fromEntries(SUBAREAS.map((s) => [s.id, s]));
  const campSub = CAMP_REGION.subareas[CAMP_REGION.subIds[0]], first = CHAIN[0];
  const CAMP = { id: 'camp', type: 'camp', x: Math.round(campSub.entry[0]), y: Math.round(campSub.entry[1]), sub: first ? first.startSub : 'camp', level: 0 };
  // The icon of an ordinary spot cycles through the sub-area's basic / armored / barrel creatures.
  const NORMAL_ROLES = ['basic', 'armored', 'barrel', 'basic', 'armored'];

  // Register every themed enemy with the rules engine.
  for (const sub of Object.keys(THEMES)) {
    for (const role of ['basic', 'tough', 'armored', 'barrel', 'boss']) {
      const [name, icon, art] = THEMES[sub][role];
      Engine.ENEMY_TYPES[sub + '_' + role] = Object.assign(
        { name, icon, art },
        role === 'barrel' ? { barrel: true, blast: 2 } : {},
        role === 'boss' ? { boss: true } : {});
    }
  }

  // ---------- Nodes ----------
  function buildWorld() {
    const nodes = [CAMP];
    for (const sub of SUBAREAS) {
      const add = (id, p, type, level, role) => nodes.push(Object.assign({ id, x: Math.round(p[0]), y: Math.round(p[1]), sub: sub.id, type, level }, role ? { role } : {}));
      const n = sub.spots.length;
      sub.spots.forEach((p, i) => {
        // The first sub-area's early spots stay at its lowest level longer (design 24.1: gentle first runs).
        const level = sub.lv[0] + Math.floor(i * (sub.lv[1] - sub.lv[0] + 1) / n);
        const role = level >= 2 || i >= 2 ? NORMAL_ROLES[i % NORMAL_ROLES.length] : 'basic';
        add(sub.id + '-' + i, p, 'battle', level, role);
      });
      const eliteLv = sub.lv[1] + (sub.regionIndex >= 1 ? 1 : 0);
      sub.elites.forEach((p, i) => add(sub.id + '-e' + i, p, 'elite', eliteLv, 'tough'));
      if (sub.poiPos) {
        // WP13: some caches are guarded (you must beat a patrol first); the guard is a normal fight at the sub-area's top level.
        const guarded = sub.poi === 'treasure' && GUARDED.includes(sub.id);
        add(sub.id + '-poi', sub.poiPos, sub.poi, guarded ? sub.lv[1] : sub.lv[0], guarded ? 'armored' : null);
        if (guarded) nodes[nodes.length - 1].guarded = true;
      }
      // WP13: a roadside Shop in every second sub-area and an Event (a short vignette) in every sub-area. Both are free of Rations.
      if (sub.shopPos && SHOPS.includes(sub.id)) add(sub.id + '-shop', sub.shopPos, 'shop', sub.lv[0]);
      if (sub.eventPos) add(sub.id + '-event', sub.eventPos, 'event', sub.lv[0]);
      // WP14: a Wayshrine (waypoint) near each sub-area's entry and a hidden Sealed Cache (secret: invisible until the hero walks close or a scout finds it; needs a key).
      if (sub.wpPos) add(sub.id + '-wp', sub.wpPos, 'waypoint', sub.lv[0]);
      if (sub.secretPos) add(sub.id + '-secret', sub.secretPos, 'secret', sub.lv[1]);
      add(sub.id + '-boss', sub.boss, 'boss', sub.bossLv, 'boss');
    }
    const byId = Object.fromEntries(nodes.map((n) => [n.id, n]));
    // Free exploration: there is no path graph any more. The empty `edges`/`adj` stay for older callers.
    return { nodes, edges: [], byId, adj: Object.fromEntries(nodes.map((n) => [n.id, []])) };
  }

  // Danger rating in skulls (design 8.1): Lv1-3 = 1, 4-6 = 2, 7-9 = 3, 10-12 = 4, 13+ = 5.
  const danger = (level) => Math.max(1, Math.min(5, Math.ceil(level / 3)));
  // The single power curve (docs/GAME_DESIGN.md "Power curve"): w(L) = (L/5)^1.5, 1.0 at Lv5 (the Greenvale boss band).
  // Reward magnitudes (Souls, Gold, run upgrades, item levels, boss Rations) are all affine in w(L), so a deeper fight is worth more per Ration.
  const power = (level) => Math.pow(Math.max(1, level) / 5, 1.5);
  // WP14 scouting: a monster spot (ordinary or elite) within `sightRadius` of where the hero has stood is revealed for good; farther ones stay
  // faint silhouettes. Hidden secrets are found within `secretRadius`. Camp "Scouting" levels widen both. MAX_KEYS = keys carried per run.
  const sightRadius = (lv) => 430 + 150 * (lv || 0);
  const secretRadius = (lv) => 130 + 50 * (lv || 0);
  const FOGGED = ['battle', 'elite'];
  const WORLD = Object.assign(buildWorld(), { sightRadius, secretRadius, FOGGED, MAX_KEYS: 3, SCOUT_GOLD: 6, danger, power, MAP_W, MAP_H, MAP_BOX, GEN: WG, FINAL_SUBS, SUBAREAS, SUB_BY, REGIONS, THEMES, CAMP, hash, rng, NORMAL_ROLES });
  root.World = WORLD;
  if (typeof module !== 'undefined' && module.exports) module.exports = WORLD;
})(typeof window !== 'undefined' ? window : globalThis);
